#include "Editor.h"
using namespace juce;
ChoirEditor::ChoirEditor(ChoirProcessor& processor):AudioProcessorEditor(processor),p(processor){
 look.setColour(Slider::rotarySliderFillColourId,Colour(0xff4bd6bd));look.setColour(Slider::rotarySliderOutlineColourId,Colour(0xff294149));look.setColour(Slider::textBoxTextColourId,Colours::white);look.setColour(Slider::textBoxOutlineColourId,Colours::transparentBlack);look.setColour(ComboBox::backgroundColourId,Colour(0xff20383d));setLookAndFeel(&look);
 const char* ids[]={"voices","detune","timing","width","mix","gain"};const char* names[]={"VOICES","PITCH SPREAD","TIMING SPREAD","STEREO WIDTH","CHOIR BLEND","OUTPUT"};const char* suffix[]={" voices"," cents"," ms"," %"," %"," dB"};
 for(int i=0;i<6;++i){auto& s=knobs[i];s.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(Slider::TextBoxBelow,false,110,26);s.setTextValueSuffix(suffix[i]);s.setName(names[i]);addAndMakeVisible(s);labels[i].setText(names[i],dontSendNotification);labels[i].setJustificationType(Justification::centred);labels[i].setColour(Label::textColourId,Colour(0xffb7ced1));addAndMakeVisible(labels[i]);attachments.push_back(std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],s));}
 presets.addItem("Small ensemble",1);presets.addItem("Full ensemble",2);presets.addItem("Wide crowd",3);presets.setTextWhenNothingSelected("Choose a starting point");presets.onChange=[this]{p.preset(presets.getSelectedId()-1);};addAndMakeVisible(presets);setSize(860,460);
}
void ChoirEditor::resized(){presets.setBounds(570,31,258,32);for(int i=0;i<6;++i){int x=26+i*136;labels[i].setBounds(x,186,128,24);knobs[i].setBounds(x,216,128,142);}}
